    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "credit-card-comparison-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "properties": {
            "children": [
              "summary_card",
              "comparison_table_card",
              "details_tabs",
              "assumptions_card"
            ]
          }
        },
        {
          "id": "summary_card",
          "component": "Card",
          "properties": {
            "children": [
              "summary_col"
            ]
          }
        },
        {
          "id": "summary_col",
          "component": "Column",
          "properties": {
            "children": [
              "summary_row",
              "summary_body"
            ]
          }
        },
        {
          "id": "summary_row",
          "component": "Row",
          "properties": {
            "children": [
              "summary_icon",
              "summary_headline"
            ],
            "verticalAlignment": "center"
          }
        },
        {
          "id": "summary_icon",
          "component": "Icon",
          "properties": {
            "icon": "/assets/r_000562_01_1_account_balance_wallet_gm_grey_24dp.png"
          }
        },
        {
          "id": "summary_headline",
          "component": "Headline",
          "properties": {
            "text": "Recommendation: Card A"
          }
        },
        {
          "id": "summary_body",
          "component": "Body",
          "properties": {
            "text": "Card A yields a higher net value of $480 per year, compared to Card B's $397, based on your specified spending habits. Therefore, Card A is the better choice for you under these circumstances."
          }
        },
        {
          "id": "comparison_table_card",
          "component": "Card",
          "properties": {
            "children": [
              "comparison_table_title",
              "comparison_table"
            ]
          }
        },
        {
          "id": "comparison_table_title",
          "component": "Title",
          "properties": {
            "text": "Comparison"
          }
        },
        {
          "id": "comparison_table",
          "component": "Table",
          "properties": {
            "columns": [
              {
                "header": "Feature"
              },
              {
                "header": "Card A",
                "horizontalAlignment": "end"
              },
              {
                "header": "Card B",
                "horizontalAlignment": "end"
              }
            ],
            "rows": [
              {
                "cells": [
                  {
                    "text": "Annual Cashback Earned"
                  },
                  {
                    "text": "$480"
                  },
                  {
                    "text": "$492"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "text": "Annual Fee"
                  },
                  {
                    "text": "$0"
                  },
                  {
                    "text": "$95"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "text": "Net Annual Value"
                  },
                  {
                    "text": "$480"
                  },
                  {
                    "text": "$397"
                  }
                ],
                "highlight": true
              }
            ]
          }
        },
        {
          "id": "details_tabs",
          "component": "Tabs",
          "properties": {
            "children": [
              "tab_a",
              "tab_b"
            ]
          }
        },
        {
          "id": "tab_a",
          "component": "Tab",
          "properties": {
            "label": "Card A Details",
            "children": [
              "card_a_col"
            ]
          }
        },
        {
          "id": "card_a_col",
          "component": "Column",
          "properties": {
            "children": [
              "card_a_title",
              "card_a_rates",
              "card_a_div1",
              "card_a_annual_title",
              "card_a_annual_kv"
            ]
          }
        },
        {
          "id": "card_a_title",
          "component": "Title",
          "properties": {
            "text": "Card A Analysis"
          }
        },
        {
          "id": "card_a_rates",
          "component": "Body",
          "properties": {
            "text": "Cashback Rate: 2% on all purchases\nAnnual Fee: $0"
          }
        },
        {
          "id": "card_a_div1",
          "component": "Divider"
        },
        {
          "id": "card_a_annual_title",
          "component": "Title",
          "properties": {
            "text": "Annual Calculations"
          }
        },
        {
          "id": "card_a_annual_kv",
          "component": "KeyValue",
          "properties": {
            "items": [
              {
                "key": "Total Annual Spending",
                "value": "$24,000"
              },
              {
                "key": "Annual Cashback Earned",
                "value": "$480"
              },
              {
                "key": "Net Annual Value",
                "value": "$480"
              }
            ]
          }
        },
        {
          "id": "tab_b",
          "component": "Tab",
          "properties": {
            "label": "Card B Details",
            "children": [
              "card_b_col"
            ]
          }
        },
        {
          "id": "card_b_col",
          "component": "Column",
          "properties": {
            "children": [
              "card_b_title",
              "card_b_rates",
              "card_b_div1",
              "card_b_monthly_title",
              "card_b_monthly_kv",
              "card_b_div2",
              "card_b_annual_title",
              "card_b_annual_kv"
            ]
          }
        },
        {
          "id": "card_b_title",
          "component": "Title",
          "properties": {
            "text": "Card B Analysis"
          }
        },
        {
          "id": "card_b_rates",
          "component": "Body",
          "properties": {
            "text": "Cashback Rates: 4% on dining/travel, 1% on everything else\nAnnual Fee: $95"
          }
        },
        {
          "id": "card_b_div1",
          "component": "Divider"
        },
        {
          "id": "card_b_monthly_title",
          "component": "Title",
          "properties": {
            "text": "Monthly Cashback"
          }
        },
        {
          "id": "card_b_monthly_kv",
          "component": "KeyValue",
          "properties": {
            "items": [
              {
                "key": "Dining Cashback",
                "value": "$20"
              },
              {
                "key": "Travel Cashback",
                "value": "$8"
              },
              {
                "key": "Other Cashback",
                "value": "$13"
              },
              {
                "key": "Total Monthly Cashback",
                "value": "$41"
              }
            ]
          }
        },
        {
          "id": "card_b_div2",
          "component": "Divider"
        },
        {
          "id": "card_b_annual_title",
          "component": "Title",
          "properties": {
            "text": "Annual Calculations"
          }
        },
        {
          "id": "card_b_annual_kv",
          "component": "KeyValue",
          "properties": {
            "items": [
              {
                "key": "Total Annual Cashback",
                "value": "$492"
              },
              {
                "key": "Net Annual Value",
                "value": "$397"
              }
            ]
          }
        },
        {
          "id": "assumptions_card",
          "component": "Card",
          "properties": {
            "children": [
              "assumptions_title",
              "assumptions_body"
            ]
          }
        },
        {
          "id": "assumptions_title",
          "component": "Title",
          "properties": {
            "text": "Assumptions"
          }
        },
        {
          "id": "assumptions_body",
          "component": "Body",
          "properties": {
            "text": "- Calculations are based on the exact monthly spending figures provided for a full year (12 months).\n- Cashback is calculated directly on the specified spend categories and rates.\n- No other fees or introductory offers are considered."
          }
        }
      ]
    }
  }
]
